#!/usr/bin/env python3
"""Generate only the pinned Unicode properties needed by native field normalization."""
import hashlib
import json
from pathlib import Path
import sys

root = Path(__file__).resolve().parent.parent
source = root / 'third_party/unicode'
manifest = json.loads((root / 'resources/unicode-source.json').read_text())
for name, expected in manifest['files'].items():
    if hashlib.sha256((source / name).read_bytes()).hexdigest() != expected:
        raise SystemExit('Pinned Unicode source changed: ' + name)

def records(version, name):
    for line in (source / version / name).read_text().splitlines():
        line = line.split('#', 1)[0].strip()
        if line:
            yield [field.strip() for field in line.split(';')]

lower, upper = {}, {}
for row in records('17.0.0', 'UnicodeData.txt'):
    cp = int(row[0], 16)
    if row[13]:
        lower[cp] = [int(row[13], 16)]
    if row[12]:
        upper[cp] = [int(row[12], 16)]
for row in records('17.0.0', 'SpecialCasing.txt'):
    if row[4]:
        # Default casing has exactly one language-independent context rule.
        if not any(language in row[4].split() for language in ['lt', 'tr', 'az']):
            assert row[:5] == ['03A3', '03C2', '03A3', '03A3', 'Final_Sigma']
        continue
    cp = int(row[0], 16)
    lower[cp] = [int(item, 16) for item in row[1].split()]
    upper[cp] = [int(item, 16) for item in row[3].split()]
for mapping in [lower, upper]:
    for cp in list(mapping):
        if mapping[cp] == [cp]:
            del mapping[cp]

properties = {'Cased': [], 'Case_Ignorable': []}
for row in records('17.0.0', 'DerivedCoreProperties.txt'):
    if row[1] in properties:
        limits = [int(cp, 16) for cp in row[0].split('..')]
        properties[row[1]].append((limits[0], limits[-1]))
for name, ranges in properties.items():
    compact = []
    for start, end in sorted(ranges):
        if compact and start <= compact[-1][1] + 1:
            compact[-1] = (compact[-1][0], max(end, compact[-1][1]))
        else:
            compact.append((start, end))
    properties[name] = compact

classes, decompositions = {}, {}
for row in records('15.1.0', 'UnicodeData.txt'):
    cp = int(row[0], 16)
    if int(row[3]):
        assert not row[1].endswith(('First>', 'Last>'))
        classes[cp] = int(row[3])
    if row[5] and not row[5].startswith('<'):
        decompositions[cp] = [int(item, 16) for item in row[5].split()]
excluded = {int(row[0], 16) for row in records('15.1.0', 'CompositionExclusions.txt')}
compositions = {}
for cp, decomposition in decompositions.items():
    # Full_Composition_Exclusion also includes singleton and non-starter decompositions.
    if cp not in excluded and len(decomposition) == 2 and classes.get(decomposition[0], 0) == 0:
        key = (decomposition[0] << 21) | decomposition[1]
        assert key not in compositions
        compositions[key] = cp

def expand(cp, path=()):
    assert cp not in path and len(path) < 32
    if cp not in decompositions:
        return [cp]
    return [part for item in decompositions[cp] for part in expand(item, (*path, cp))]

decomposed = {cp: expand(cp) for cp in decompositions}
assert max(map(len, decomposed.values())) <= 4
assert max(map(len, lower.values())) <= 3 and max(map(len, upper.values())) <= 3
lines = [
    '// Generated by tools/generate-unicode-data.py from pinned Unicode data. Do not edit.',
    '// Unicode License V3: third_party/unicode/LICENSE.',
    '#ifndef KUMWE_ENGINE_UNICODE_DATA_HPP', '#define KUMWE_ENGINE_UNICODE_DATA_HPP',
    '#include <cstdint>', '#include <cstddef>',
    'namespace kumwe::engine::document::unicode_data {',
    'struct mapping { std::uint32_t point; std::uint32_t values[4]; std::uint8_t size; };',
    'struct range { std::uint32_t first; std::uint32_t last; };',
    'struct combining { std::uint32_t point; std::uint8_t value; };',
    'struct composition { std::uint64_t pair; std::uint32_t point; };',
]
for name, data in [('lowercase', lower), ('uppercase', upper), ('decomposition', decomposed)]:
    lines.append('inline constexpr mapping ' + name + '[] = {')
    for cp, values in sorted(data.items()):
        padded = values + [0] * (4 - len(values))
        lines.append('    {' + str(cp) + ', {' + ', '.join(map(str, padded)) + '}, ' + str(len(values)) + '},')
    lines.append('};')
for name, ranges in properties.items():
    lines.append('inline constexpr range ' + name.lower() + '[] = {')
    lines.extend('    {' + str(start) + ', ' + str(end) + '},' for start, end in ranges)
    lines.append('};')
lines.append('inline constexpr combining classes[] = {')
lines.extend('    {' + str(cp) + ', ' + str(value) + '},' for cp, value in sorted(classes.items()))
lines.extend(['};', 'inline constexpr composition compositions[] = {'])
lines.extend('    {' + str(pair) + 'ULL, ' + str(cp) + '},' for pair, cp in sorted(compositions.items()))
lines.extend(['};', '}', '#endif', ''])
generated = '\n'.join(lines)
target = root / 'src/document/unicode_data.hpp'
if sys.argv[1:] == ['--check']:
    if target.read_text() != generated:
        raise SystemExit('Generated Unicode tables differ from pinned normative inputs.')
elif sys.argv[1:]:
    raise SystemExit('Usage: generate-unicode-data.py [--check]')
else:
    target.write_text(generated)
print(f'Unicode 17 casing / 15.1 NFC tables verified: {len(lower)} lower, {len(upper)} upper, '
      f'{len(decomposed)} decompositions, {len(compositions)} compositions.')
